// A tiny in-memory todo store.
const todos = [];
let nextId = 1;
export function add(title) {
  if (!title || !title.trim()) throw new Error('title required');
  const t = { id: nextId++, title: title.trim(), done: false };
  todos.push(t);
  return t;
}
export function complete(id) {
  const t = todos.find((x) => x.id == id);
  if (!t) throw new Error('not found');
  t.done = true;
  return t;
}
// BUG: should return only todos that are not done.
export function open() { return todos.filter((t) => t.done); }
export function all() { return [...todos]; }
export function reset() { todos.length = 0; nextId = 1; }

