import { test, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { add, complete, open, all, reset } from '../src/todos.js';
beforeEach(() => reset());
test('add trims and numbers', () => { assert.deepEqual(add('  milk '), { id: 1, title: 'milk', done: false }); });
test('open lists unfinished todos', () => { add('a'); add('b'); complete(1); assert.deepEqual(open().map((t) => t.title), ['b']); });
test('all lists everything', () => { add('a'); add('b'); assert.equal(all().length, 2); });

